insert into public.programs (id, data, created_at) values
  ('CT', '{"id":"CT","track":1,"lvl":1,"en":"Certified Trainer","ar":"مدرب معتمد","den":"For professionals stepping into the educational sphere to guide, mentor, and train the next generation of beauty practitioners.","dar":"للمحترفين الذين ينتقلون إلى المجال التعليمي لتوجيه وتدريب الجيل القادم من ممارسي التجميل.","wen":"Experienced practitioners ready to teach","war":"ممارسون ذوو خبرة مستعدون للتدريس","oen":"Licensed to deliver accredited training","oar":"تأهيل لتقديم تدريب معتمد"}'::jsonb, now() + interval '0 seconds'),
  ('IET', '{"id":"IET","track":1,"lvl":2,"en":"International Expert Trainer","ar":"مدرب خبير دولي","den":"An advanced credential for seasoned educators delivering world-class training and masterclasses on a global scale.","dar":"اعتماد متقدّم للمدربين المتمرسين الذين يقدّمون تدريباً وورش عمل احترافية على مستوى عالمي.","wen":"Certified trainers teaching across borders","war":"مدربون معتمدون يدرّبون على المستوى الدولي","oen":"International masterclass authority","oar":"صلاحية تقديم ورش احترافية دولية"}'::jsonb, now() + interval '1 seconds'),
  ('CC', '{"id":"CC","track":2,"lvl":1,"en":"Certified Consultant","ar":"مستشار معتمد","den":"For industry professionals providing trusted advisory, business, and strategic services to salons, clinics, and beauty brands.","dar":"للمحترفين الذين يقدّمون استشارات موثوقة وخدمات إدارية واستراتيجية للصالونات والعيادات وعلامات التجميل.","wen":"Salon & clinic owners, managers, advisors","war":"مالكو ومديرو الصالونات والعيادات والمستشارون","oen":"Recognized advisory practice","oar":"ممارسة استشارية معترف بها"}'::jsonb, now() + interval '2 seconds'),
  ('IEC', '{"id":"IEC","track":2,"lvl":2,"en":"International Expert Consultant","ar":"مستشار خبير دولي","den":"A top-tier designation for consultants leading large-scale industry projects and providing expert international advisory initiatives.","dar":"لقب رفيع للمستشارين الذين يقودون مشاريع كبرى في القطاع ويقدّمون مبادرات استشارية دولية.","wen":"Consultants leading multi-site or cross-border work","war":"مستشارون يقودون مشاريع متعددة الفروع أو عابرة للحدود","oen":"International advisory mandate","oar":"صلاحية استشارية دولية"}'::jsonb, now() + interval '3 seconds'),
  ('PM', '{"id":"PM","track":3,"lvl":1,"en":"Professional Master''s Degree","ar":"الماجستير المهني","den":"A specialized, high-level program designed to deepen industry expertise, operational knowledge, and corporate leadership capabilities.","dar":"برنامج متخصص رفيع المستوى لتعميق الخبرة في القطاع والمعرفة التشغيلية والقدرات القيادية المؤسسية.","wen":"Managers and senior practitioners","war":"المديرون والممارسون الأقدم","oen":"Corporate leadership qualification","oar":"مؤهل في القيادة المؤسسية"}'::jsonb, now() + interval '4 seconds'),
  ('PD', '{"id":"PD","track":3,"lvl":2,"en":"Professional Doctorate","ar":"الدكتوراه المهنية","den":"The pinnacle of professional achievement, awarded to pioneers, researchers, and thought leaders driving innovation across the global beauty sector.","dar":"قمّة الإنجاز المهني، تُمنح للروّاد والباحثين وقادة الفكر الذين يقودون الابتكار في قطاع التجميل العالمي.","wen":"Pioneers, researchers, thought leaders","war":"الروّاد والباحثون وقادة الفكر","oen":"Highest professional distinction","oar":"أعلى درجة مهنية"}'::jsonb, now() + interval '5 seconds')
insert into public.services (id, data, created_at) values
  ('SV-1', '{"ic":"train","en":"Accredited Vocational Training","ar":"التدريب المهني المعتمد","den":"World-class practical and theoretical training delivered by certified expert trainers, in-person and online.","dar":"تدريب عملي ونظري عالمي المستوى يقدّمه مدربون خبراء معتمدون، حضورياً وعن بُعد.","len":["Masterclasses & workshops","Train-the-trainer cohorts","Blended online learning"],"lar":["ورش عمل وماستر كلاس","دفعات إعداد المدربين","تعلّم مدمج عبر الإنترنت"],"id":"SV-1"}'::jsonb, now() + interval '0 seconds'),
  ('SV-2', '{"ic":"cert","en":"Professional Credentials","ar":"الاعتمادات المهنية","den":"Globally recognized certifications and professional degrees, from Certified Trainer to Professional Doctorate.","dar":"شهادات ودرجات مهنية معترف بها دولياً، من المدرب المعتمد حتى الدكتوراه المهنية.","len":["Six credential levels","Portfolio assessment","Online verification"],"lar":["ستة مستويات اعتماد","تقييم ملف الإنجاز","تحقق إلكتروني"],"id":"SV-2"}'::jsonb, now() + interval '1 seconds'),
  ('SV-3', '{"ic":"strat","en":"Strategic & Business Advisory","ar":"الاستشارات الاستراتيجية والإدارية","den":"Growth strategy, market entry, pricing and brand positioning for beauty businesses.","dar":"استراتيجيات النمو ودخول الأسواق والتسعير وتموضع العلامة لمنشآت التجميل.","len":["Business plans & feasibility","Brand positioning","Expansion & franchising"],"lar":["خطط العمل ودراسات الجدوى","تموضع العلامة التجارية","التوسع والامتياز التجاري"],"id":"SV-3"}'::jsonb, now() + interval '2 seconds'),
  ('SV-4', '{"ic":"salon","en":"Salon & Clinic Operations","ar":"تطوير تشغيل الصالونات والعيادات","den":"Operational audits and quality systems that lift service standards, hygiene and client experience.","dar":"تدقيق تشغيلي وأنظمة جودة ترفع معايير الخدمة والنظافة وتجربة العميل.","len":["Operational audits","SOPs & quality manuals","Staff performance systems"],"lar":["تدقيق تشغيلي","إجراءات تشغيل وأدلة جودة","أنظمة أداء الموظفين"],"id":"SV-4"}'::jsonb, now() + interval '3 seconds'),
  ('SV-5', '{"ic":"lead","en":"Leadership Development","ar":"تطوير القيادات","den":"Executive programs that build managers and directors for academies, chains and brands.","dar":"برامج تنفيذية تُعدّ المديرين والقادة للأكاديميات وسلاسل الصالونات والعلامات التجارية.","len":["Professional Master''s track","Executive coaching","Research & innovation"],"lar":["مسار الماجستير المهني","التوجيه التنفيذي","البحث والابتكار"],"id":"SV-5"}'::jsonb, now() + interval '4 seconds'),
  ('SV-6', '{"ic":"cpd","en":"CPD & Membership","ar":"التطوير المهني المستمر والعضوية","den":"Continuing Professional Development hours and an international member network that keeps skills current.","dar":"ساعات تطوير مهني مستمر وشبكة أعضاء دولية تبقي مهاراتك محدّثة.","len":["American CPD-validated hours","Member events","Annual renewal"],"lar":["ساعات معتمدة من American CPD","فعاليات الأعضاء","تجديد سنوي"],"id":"SV-6"}'::jsonb, now() + interval '5 seconds')
